import { JSDOM } from "jsdom";
import { Editor, type EditorOptions } from "@tiptap/core";
import { StarterKit } from "@tiptap/starter-kit";
import { CommentMark } from "./extensions/comment-mark";
import { PersonaNoteMark } from "./extensions/persona-note-mark";
import { SuggestionMark } from "./extensions/suggestion-mark";
import { PageBreakNode } from "./extensions/page-break-node";

/**
 * Tiptap + JSDOM test harness. The project's editor mounts inside a
 * Qwik component, which is too much ceremony to drive under test; the
 * extensions and the documents they operate on, however, are pure and
 * cover the lion's share of the bug surface (mark shape, anchor
 * preservation, setComment command, etc.). This file stands up a
 * minimal JSDOM, installs the project extensions on a fresh editor,
 * and yields the editor for the test to drive.
 *
 * Tests should not import this file directly. They use the `withEditor`
 * helper, which handles setup, teardown, and DOM global management in
 * one call.
 */

export interface EditorHarness {
  dom: JSDOM;
  editor: Editor;
  host: HTMLElement;
  /** Convenience for tests that need to read the rendered HTML. */
  html: () => string;
}

export interface WithEditorOptions {
  content?: string;
  /** Extra extensions on top of the project's standard set. */
  extensions?: EditorOptions["extensions"];
}

/**
 * Standard Tiptap extensions used by the project's editor.
 *
 * The pagination extension is deliberately absent: JSDOM has no layout
 * engine, so every `offsetHeight` it reports is zero and the measurements
 * would be meaningless. Pagination's arithmetic is tested directly against
 * `pagination-geometry.ts`, and its DOM behaviour in the Playwright suite.
 */
export const projectExtensions = [
  StarterKit,
  CommentMark,
  PersonaNoteMark,
  SuggestionMark,
  PageBreakNode,
];

/**
 * Mount a Tiptap editor in a fresh JSDOM and yield it to the test.
 * Installs DOM globals for the lifetime of the callback, then tears
 * them down so a follow-up test gets a clean slate.
 */
export async function withEditor(
  opts: WithEditorOptions | ((harness: EditorHarness) => Promise<void> | void),
  run?: (harness: EditorHarness) => Promise<void> | void,
): Promise<void> {
  // Backwards-compatible: `withEditor(cb)` still works.
  if (typeof opts === "function") {
    run = opts as (h: EditorHarness) => Promise<void> | void;
    opts = {};
  }
  const options = (opts ?? {}) as WithEditorOptions;

  const dom = new JSDOM(
    `<!DOCTYPE html><html><body><div id="editor-mount"></div></body></html>`,
  );

  const previousGlobals: Record<string, unknown> = {};
  const install = (key: string, value: unknown) => {
    previousGlobals[key] = (globalThis as Record<string, unknown>)[key];
    (globalThis as Record<string, unknown>)[key] = value;
  };

  install("document", dom.window.document);
  install("window", dom.window);
  install("HTMLElement", dom.window.HTMLElement);
  install("Node", dom.window.Node);
  install("Element", dom.window.Element);
  install("navigator", dom.window.navigator);
  install("getComputedStyle", dom.window.getComputedStyle);
  // Tiptap's `keyboardShortcut` command synthesises a real KeyboardEvent to
  // run it through the keymap, so a test that exercises a binding needs the
  // constructor on the global rather than only on the JSDOM window.
  install("Event", dom.window.Event);
  install("KeyboardEvent", dom.window.KeyboardEvent);
  install("MouseEvent", dom.window.MouseEvent);
  install(
    "requestAnimationFrame",
    (cb: FrameRequestCallback) => setTimeout(() => cb(0), 0) as unknown as number,
  );
  install("cancelAnimationFrame", (id: number) => clearTimeout(id));

  const host = document.getElementById("editor-mount")!;
  const editor = new Editor({
    element: host,
    extensions: [...projectExtensions, ...(options.extensions ?? [])],
    content: options.content ?? "",
  });

  const harness: EditorHarness = {
    dom,
    editor,
    host,
    html: () => editor.getHTML(),
  };

  try {
    await run?.(harness);
  } finally {
    editor.destroy();
    dom.window.close();
    for (const key of Object.keys(previousGlobals)) {
      (globalThis as Record<string, unknown>)[key] = previousGlobals[key];
    }
  }
}

 * paper-3 is the in-flight / pending state (deliberately
 * quiet so it doesn't fight the cursor), and accent-green is
 * the steady "you are saved" state.
 */
export function statusColor(status: SyncStatus): string {
  switch (status.kind) {
    case "offline":
    case "error":
      return "var(--color-vermilion)";
    case "pending":
    case "syncing":
      return "var(--color-paper-3)";
    case "synced":
      return "var(--color-accent-green)";
    case "local-only":
      return "var(--color-ink-muted)";
  }
}

/**
 * Single-line human description shown in the dot's tooltip.
 * Keeps the toolbar label short while the colophon line carries
 * the timestamp.
 */
export function statusLabel(
  status: SyncStatus,
  now: number = Date.now(),
): string {
  switch (status.kind) {
    case "local-only":
      return "Local only — sign in to sync across devices";
    case "offline":
      return "Offline — your changes are still being saved locally";
    case "pending":
      return "Queued for sync…";
    case "syncing":
      return "Syncing…";
    case "synced":
      return `Synced ${formatAge(status.lastSyncedAt, now)}`;
    case "error": {
      const safetyCopy = /local work remains safe/i.test(status.message)
        ? ""
        : " Your local work remains safe on this device.";
      return `Sync failed ${formatAge(status.lastErrorAt, now)} — ${status.message}${safetyCopy}`;
    }
  }
}

